import{_ as i,a0 as r,w as n,s as a,ao as h,I as p,x as e,a1 as o,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux有問必答：如何在腳本中獲取進程ID（PID） | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在腳本中獲取進程ID（PID） | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在腳本中獲取進程ID（PID） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在腳本中獲取進程ID（PID） | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150209 Linux FAQs with Answers--How to get the process ID (PID) of a shell script","title":"Linux有問必答：如何在腳本中獲取進程ID（PID）","tag":"201503","desc":""},"relativePath":"201503/20150209 Linux FAQs with Answers--How to get the process ID (PID) of a shell script.md","filePath":"[post].md"}'),D={name:"201503/20150209 Linux FAQs with Answers--How to get the process ID (PID) of a shell script.md"};function d(I,t,u,P,f,m){const s=r("Link");return n(),a("div",null,[t[11]||(t[11]=h(`<h1 id="linux有問必答-如何在腳本中獲取進程id-pid" tabindex="-1">Linux有問必答：如何在腳本中獲取進程ID（PID） <a class="header-anchor" href="#linux有問必答-如何在腳本中獲取進程id-pid" aria-label="Permalink to “Linux有問必答：如何在腳本中獲取進程ID（PID）”">​</a></h1><blockquote><p><strong>提問</strong>: 我想要知道運行中腳本子shell的進程id。我該如何在shell腳本中得到PID。</p></blockquote><p>當我在執行shell腳本時，它會啓動一個叫子shell的進程。作為主shell的子進程，子shell將shell腳本中的命令作為批處理運行（因此稱為“批處理進程”）。</p><p>在某些情況下，你也許想要知道運行中的子shell的PID。這個PID信息可以在不同的情況下使用。比如，你可以使用shell腳本的PID在/tmp下創建一個唯一的臨時文件。有時侯腳本需要檢測所有運行的進程，它可以從進程列表中排除自身的子shell。</p><p>在bash中，<strong>子shell進程的PID</strong>存儲在一個特殊的變量‘$$’中。這個變量只讀，你不可以在腳本中修改它。比如：</p><pre><code>#!/bin/bash
 
echo &quot;PID of this script: $$&quot;
</code></pre><p>上面的腳本會得到下面的輸出：</p><pre><code>PID of this script: 6583
</code></pre><p>除了$$, bash shell還會導出其他的只讀變量。比如，PPID存儲子shell父進程的ID（也就是主shell）。UID存儲了執行這個腳本的當前用户ID。比如：</p><pre><code>#!/bin/bash
 
echo &quot;PID of this script: $$&quot;
echo &quot;PPID of this script: $PPID&quot;
echo &quot;UID of this script: $UID&quot;
</code></pre><p>輸出是：</p><pre><code>PID of this script: 6686
PPID of this script: 4656
UID of this script: 1000
</code></pre><p>上面輸出中，PID每次執行都會變化。這個因為每次運行都會創建一個新的shell。另一方面，PPID每次都會一樣只要你在同一個shell中運行。</p><p><img src="https://farm8.staticflickr.com/7437/16274890369_e78ce16d42_b.jpg" alt=""></p><p>對於所有bash內置變量列表，參考man頁。</p><pre><code>$ man bash
</code></pre><hr>`,17)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(s,{href:"http://ask.xmodulo.com/process-id-pid-shell-script.html"},{default:l(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/process-id-pid-shell-script.html",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("譯者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),o(s,{href:"http://linux.cn/"},{default:l(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const T=i(D,[["render",d]]);export{_ as __pageData,T as default};
